import kotlin.jvm.Synchronized

@org.springframework.stereotype.Component
class Good : SomeParent() {
    @Synchronized
    fun mutateSynchronized(key: String, value: String) {
        map.put(key, value)
    }
}

@org.springframework.stereotype.Component
class Good : SomeParent() {
    val lock = Any()

    fun mutateSyncBlock(key: String, value: String) {
        synchronized(lock) {
            map.put(key, value)
        }
    }
}

